package cmd;

/** A reversible edit on a document. */
@FunctionalInterface
public interface Command {
    /**
     * Applies this edit and returns the command that exactly reverses it.
     *
     * @throws IllegalArgumentException if the edit is invalid; the document is then unchanged
     */
    Command apply(StringBuilder doc);
}

package cmd;

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Objects;

/** Text editor with bounded undo/redo history and save-point tracking. */
public final class Editor {
    /** One history step: the command that reverses it, and the revisions either side. */
    private record Entry(Command reverse, long from, long to) {}

    private final StringBuilder doc = new StringBuilder();
    private final Deque<Entry> undoStack = new ArrayDeque<>();
    private final Deque<Entry> redoStack = new ArrayDeque<>();
    private final int limit;
    private long revision;
    private long counter;
    private long savedRevision;

    public Editor(int historyLimit) {
        if (historyLimit < 1) {
            throw new IllegalArgumentException("historyLimit must be >= 1");
        }
        this.limit = historyLimit;
    }

    /** Executes a command; clears redo history only if it succeeds. */
    public void execute(Command command) {
        Objects.requireNonNull(command, "command");
        Command inverse = command.apply(doc);
        long next = ++counter;
        undoStack.push(new Entry(inverse, revision, next));
        if (undoStack.size() > limit) {
            undoStack.removeLast();
        }
        redoStack.clear();
        revision = next;
    }

    public boolean undo() {
        return step(undoStack, redoStack);
    }

    public boolean redo() {
        return step(redoStack, undoStack);
    }

    private boolean step(Deque<Entry> from, Deque<Entry> to) {
        Entry e = from.peek();
        if (e == null) {
            return false;
        }
        Command opposite = e.reverse().apply(doc);
        from.pop();
        to.push(new Entry(opposite, e.to(), e.from()));
        revision = e.from();
        return true;
    }

    public boolean canUndo() {
        return !undoStack.isEmpty();
    }

    public boolean canRedo() {
        return !redoStack.isEmpty();
    }

    public String text() {
        return doc.toString();
    }

    public void save() {
        savedRevision = revision;
    }

    public boolean isDirty() {
        return revision != savedRevision;
    }
}

package cmd;

import java.util.ArrayList;
import java.util.List;
import java.util.Objects;

/** Factory for the built-in edit commands. Commands are stateless and reusable. */
public final class Commands {
    private Commands() {}

    private static void checkRange(StringBuilder doc, int pos, int length) {
        if (pos < 0 || length < 0 || pos > doc.length() || length > doc.length() - pos) {
            throw new IllegalArgumentException(
                    "range [" + pos + ", +" + length + ") outside document of length " + doc.length());
        }
    }

    /** Inserts {@code text} at {@code pos} (0..length inclusive). */
    public static Command insert(int pos, String text) {
        Objects.requireNonNull(text, "text");
        return doc -> {
            checkRange(doc, pos, 0);
            doc.insert(pos, text);
            return delete(pos, text.length());
        };
    }

    /** Deletes {@code length} chars starting at {@code pos}. */
    public static Command delete(int pos, int length) {
        return doc -> {
            checkRange(doc, pos, length);
            String removed = doc.substring(pos, pos + length);
            doc.delete(pos, pos + length);
            return insert(pos, removed);
        };
    }

    /** Replaces {@code length} chars at {@code pos} with {@code text}. */
    public static Command replace(int pos, int length, String text) {
        Objects.requireNonNull(text, "text");
        return doc -> {
            checkRange(doc, pos, length);
            String removed = doc.substring(pos, pos + length);
            doc.replace(pos, pos + length, text);
            return replace(pos, text.length(), removed);
        };
    }

    /** Runs the steps in order; atomic: on failure earlier steps are rolled back. */
    public static Command macro(List<Command> steps) {
        List<Command> copy = List.copyOf(steps);
        return doc -> {
            List<Command> inverses = new ArrayList<>();
            try {
                for (Command c : copy) {
                    inverses.add(c.apply(doc));
                }
            } catch (RuntimeException ex) {
                for (int i = inverses.size() - 1; i >= 0; i--) {
                    inverses.get(i).apply(doc);
                }
                throw ex;
            }
            List<Command> reversed = new ArrayList<>(inverses);
            java.util.Collections.reverse(reversed);
            return macro(reversed);
        };
    }
}

